<?php require 'config/db.php';$pageTitle='Student Inquiry';$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){$fields=['student_name','email','phone','subject','message'];$d=[];foreach($fields as $f){$d[$f]=trim((string)($_POST[$f]??''));if($d[$f]==='')$errors[]='All fields are required.';}if(!valid_csrf())$errors[]='Security check failed.';if(!filter_var($d['email'],FILTER_VALIDATE_EMAIL))$errors[]='Invalid email.';if(!preg_match('/^[0-9+()\- ]{10,20}$/',$d['phone']))$errors[]='Invalid phone.';if(!$errors){try{$pdo->prepare('INSERT INTO inquiries (student_name,email,phone,subject,message) VALUES (?,?,?,?,?)')->execute(array_values($d));$_SESSION['inquiry_success']=true;redirect('inquiry.php?success=1');}catch(PDOException $e){$errors[]='Unable to save inquiry.';}}}include 'includes/header.php';?><div class="container py-5"><div class="form-panel mx-auto"><h1 class="fw-bold">Student Inquiry</h1><p>Have a question? Send us a message.</p><?php if(isset($_GET['success'])&&!empty($_SESSION['inquiry_success'])):unset($_SESSION['inquiry_success']);?><div class="alert alert-success">Thanks! Your inquiry has been received.</div><?php endif;?><?php if($errors):?><div class="alert alert-danger"><?=e(implode(' ',array_unique($errors)))?></div><?php endif;?><form method="post" class="needs-validation" novalidate><input type="hidden" name="csrf" value="<?=e(csrf())?>"><?php foreach(['student_name'=>'Student Name','email'=>'Email','phone'=>'Phone','subject'=>'Subject'] as $f=>$label):?><div class="mb-3"><label class="form-label"><?=$label?></label><input class="form-control" name="<?=$f?>" type="<?=$f==='email'?'email':'text'?>" maxlength="200" value="<?=e($_POST[$f]??'')?>" required></div><?php endforeach;?><div class="mb-3"><label class="form-label">Message</label><textarea class="form-control" name="message" rows="5" required><?=e($_POST['message']??'')?></textarea></div><button class="btn btn-primary btn-lg">Send Inquiry</button></form></div></div><?php include 'includes/footer.php';?>
